function cssShape (value) {
 const root=postcss.parse(value), records=[];
 function rule (node) {
  assert.equal(node.type,"rule");const selectorsAst=selectors().astSync(node.selector);assert.ok(selectorsAst.nodes.length>=1);
  for(const selector of selectorsAst.nodes){assert.ok(selector.toString().trimStart().startsWith('.ui-surface[data-active-plan-docket="true"]'));}
  const declarations=node.nodes.map(child=>{assert.equal(child.type,"decl");assert.equal(!!child.important,false);return [child.prop,child.value,!!child.important];});
  assert.equal(new Set(declarations.map(([key])=>key)).size,declarations.length);return [node.selector,declarations];
 }
 for(const node of root.nodes){
  if(node.type==="comment"){records.push(["comment",node.text]);continue;}
  if(node.type==="rule"){records.push(["rule",...rule(node)]);continue;}
  assert.equal(node.type,"atrule");assert.equal(node.name,"media");assert.equal(node.params,"(min-width: 1024px)");
  assert.equal(node.nodes.length,1);records.push(["media",node.params,rule(node.nodes[0])]);
 }
 return records;
}
