test("actual shared-hook task owner preserves same membership refresh, resets scoped/reordered/shrunk membership and clamps requests",()=>{
 const actual=controlled(),group=(repo="EA",plan="shared.txt",count=103)=>actual.groupActivePlans(Array.from({length:count},(_,i)=>task(repo,plan,"I"+i,"in-progress")))[0];
 const h=mountDetails(group());h.pager().props.onPageChange(2);h.update(group());assert.equal(h.pager().props.page.page,2);assert.equal(h.cards().length,50);
 const refreshed=group();refreshed.tasks.forEach(t=>{t.title="Refreshed "+t.title;});h.update(refreshed);assert.equal(h.pager().props.page.page,2);
 h.pager().props.onPageChange(99);h.update(refreshed);assert.equal(h.pager().props.page.page,3);assert.equal(h.cards().length,3);
 h.update(group("UM"));assert.equal(h.pager().props.page.page,1);h.pager().props.onPageChange(2);h.update(group("UM","other.txt"));assert.equal(h.pager().props.page.page,1);
 const reordered=group("UM","other.txt");reordered.inProgress.reverse();h.pager().props.onPageChange(2);h.update(reordered);assert.equal(h.pager().props.page.page,1);
 h.update(group("UM","other.txt",1));assert.equal(h.pager(),undefined);assert.equal(h.cards().length,1);
 const a=mountDetails(group("EA")),b=mountDetails(group("UM"));a.pager().props.onPageChange(2);a.update(group("EA"));b.update(group("UM"));assert.equal(a.pager().props.page.page,2);assert.equal(b.pager().props.page.page,1);
});
